style.css:
@-moz-document domain("roblox.com") {
body, html {
    background: url("https://www.google.com/url?sa=i&url=https%3A%2F%2Fwww.wallpaperflare.com%2Fsearch%3Fwallpaper%3Dshoujo%2Bshuumatsu%2Bryokou&psig=AOvVaw1ZgzdAJ_c0e0Msg9TuSVbV&ust=1756674408588000&source=images&cd=vfe&opi=89978449&ved=0CBYQjRxqFwoTCJiCmaO4s48DFQAAAAAdAAAAABAE") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
  }

  /* Optional: Make main content backgrounds semi-transparent */
  .container-main, .content, .section, .game-card, .rbx-card {
    background-color: rgba(0, 0, 0, 0.5) !important;
    border: none !important;
  }

  /* Optional: Make headers and menus darker for readability */
  .navbar, .header, .footer, .rbx-header {
    background-color: rgba(0, 0, 0, 0.7) !important;
    color: #ffffff !important;
  }

  /* Hide annoying ads or banners (optional) */
  .ads-container, .ad-container, .advertisement {
    display: none !important;
  }

  /* Optional: Adjust font for better contrast */
  * {
    color: #e0e0e0 !important;
  }
}
